const LESS_THAN_20: [&str; 20] = ["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];
const TENS: [&str; 10] = ["","Ten","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];
const THOUSANDS: [&str; 4] = ["","Thousand","Million","Billion"];

fn convert(n: i32) -> String {
  if n == 0 { return String::new(); }
  if n < 20 { return LESS_THAN_20[n as usize].to_string(); }
  if n < 100 {
    let t = TENS[(n/10) as usize].to_string();
    let r = convert(n % 10);
    return if r.is_empty() { t } else { t + " " + &r };
  }
  let h = (LESS_THAN_20[(n/100) as usize]).to_string() + " Hundred";
  let r = convert(n % 100);
  return if r.is_empty() { h } else { h + " " + &r };
}

fn number_to_words(num: i32) -> String {
  if num == 0 { return "Zero".to_string(); }
  let mut n = num;
  let mut result = String::new();
  let mut i = 0;
  while n > 0 {
    let chunk = n % 1000;
    if chunk > 0 {
      let chunk_words = convert(chunk);
      let mag = THOUSANDS[i];
      let prefix = if mag.is_empty() { chunk_words } else { chunk_words + " " + mag };
      result = if result.is_empty() { prefix } else { prefix + " " + &result };
    }
    n /= 1000;
    i += 1;
  }
  result
}

fn main() {
  let mut input = String::new();
  std::io::stdin().read_line(&mut input).unwrap();
  let num: i32 = input.trim().parse().unwrap();
  println!("{}", number_to_words(num));
}
